/**
 * @name Path traversal via URL parsing
 * @description User-controlled input used in URL parsing could lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-url
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module UrlPathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for URL parsing operations that could be used for path traversal
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib.parse").getMember(["urlparse", "urlsplit", "parse_qs", "parse_qsl"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("mdurl").getMember(["parse", "decode", "encode"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module UrlPathTraversalFlow = TaintTracking::Global<UrlPathTraversalConfig>;
import UrlPathTraversalFlow::PathGraph

from UrlPathTraversalFlow::PathNode source, UrlPathTraversalFlow::PathNode sink
where UrlPathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal via URL parsing from $@.", source.getNode(), "user input"
